                            || transient_error[-srcdefn->ctx->last_errno] == 0 ) )
                        return srcdefn->ctx->last_errno;
                    else
                    {
                        geodetic_loc.u = HUGE_VAL;
                        geodetic_loc.v = HUGE_VAL;
                    }
                }

